PUBLIC BRIEF: {"buyer":"UNFPA / PSA guide","exclusions":["No obtaining drafts, source retrieval, link validation or invention of case-study evidence.","No guide authorship, specialist hiring, production meetings or publication design.","Only proposed scoping artifacts; the customer engagement is not executed."],"id":"unfpa-psa-revision-workplan","requirements":[{"brick":"review","id":"R1","owner":"blocked_private_input","text":"Identify remaining revisions from the revised outline and partially revised guide."},{"brick":"plan","id":"R2","owner":"agent_draft","text":"Deliver an inception report and revision workplan."},{"brick":"draft","id":"R3","owner":"human_required","text":"Generate or obtain missing drafts with the Reference Group."},{"brick":"review","id":"R4","owner":"blocked_private_input","text":"Develop case studies and update reference links."},{"brick":"draft","id":"R5","owner":"human_required","text":"Coordinate figures, tables and proposed production design with specialists."},{"brick":"report","id":"R6","owner":"blocked_private_input","text":"Deliver initial and final guide versions with consistent narrative and analytical approach."}],"source_url":"https://www.unfpa.org/jobs/consultancy-lead-writer-and-editor-revised-unfpa-publication-population-and-situational","summary":"Complete a methodological guide from a revised outline and partial revisions, with an inception report, workplan, initial draft and final version. This test scopes revision work and missing-input dependencies only.","title":"Population and Situational Analysis guide revision"}
